def signal(obs):
    try:
        n=150
        mA=obs.hist('A','mid', n)
        mB=obs.hist('B','mid', n)
        mC=obs.hist('C','mid', n)
        mI=obs.hist('IDX','mid', n)
        if mA is None or mB is None or mC is None or mI is None:
            return {}
        # need enough history
        if len(mA)<120:
            return {}
        synth=0.3333*mA+0.6667*mB+0.1667*mC
        spread=synth-mI
        # mask nans early
        valid=spread[np.isfinite(spread)]
        if len(valid)<100:
            return {}
        mu=np.nanmean(valid)
        sd=np.nanstd(valid)
        if not np.isfinite(mu) or not np.isfinite(sd) or sd<1.5:
            return {}
        cur_spread=spread[-1]
        if not np.isfinite(cur_spread):
            return {}
        z=(cur_spread-mu)/sd
        # state for fixed horizon holding
        if 'hold' not in obs.state:
            obs.state['hold']=0
            obs.state['pos']=0.0
        # countdown hold
        if obs.state['hold']>0:
            obs.state['hold']-=1
            # if hold expires, check if should exit or extend
            if obs.state['hold']==0:
                if abs(z)<0.6:
                    obs.state['pos']=0.0
                else:
                    # if still stretched same direction, keep holding a bit longer
                    if (obs.state['pos']>0 and z>1.0) or (obs.state['pos']<0 and z<-1.0):
                        obs.state['hold']=3
                    else:
                        obs.state['pos']=0.0
            return {'IDX': float(obs.state['pos'])}
        # not in hold, look for entry
        if z>1.8:
            obs.state['pos']=1.0
            obs.state['hold']=5
            return {'IDX': 1.0}
        elif z<-1.8:
            obs.state['pos']=-1.0
            obs.state['hold']=5
            return {'IDX': -1.0}
        elif abs(z)<0.5:
            obs.state['pos']=0.0
            return {'IDX': 0.0}
        else:
            # keep previous (flat)
            if obs.state['pos']!=0:
                return {'IDX': float(obs.state['pos'])}
            return {}
    except:
        return {}

