        try:
            v = obs.hist(a, 'mid', n)
            if v is None:
                return None
            # take last finite value
            for i in range(len(v)-1, -1, -1):
                x = v[i]
                if x == x: # not NaN
                    return float(x)
            return None
        except:
            return None
    ma = mid('A', 3)
    mb = mid('B', 3)
    mc = mid('C', 3)
    mi = mid('IDX', 3)
    maX = mid('A.X', 3)
    mbX = mid('B.X', 3)
    mcX = mid('C.X', 3)
    if ma is None or mb is None or mc is None or mi is None:
        return {}
    # use average of primary and alternate venues to stabilise synthetic
    if maX is not None:
        ma = (ma + maX) * 0.5
    if mbX is not None:
        mb = (mb + mbX) * 0.5
    if mcX is not None:
        mc = (mc + mcX) * 0.5
    synth = 0.3333*ma + 0.6667*mb + 0.1667*mc
    spread = mi - synth  # >0 IDX rich
    # scale by ~1 sigma (43). 40 gives good sensitivity
    z = spread / 40.0
    if z > 1.0:
        z = 1.0
    if z < -1.0:
        z = -1.0
    # dead zone to cut churn on small noise (~16 cents)
    if abs(z) < 0.40:
        return {'IDX': 0.0}
    # mean reversion: short rich IDX, long cheap IDX
    t = -z
    # clip
    if t > 1: t=1
    if t < -1: t=-1
    return {'IDX': float(t)}

